#!/usr/bin/env python3
"""Collect every AI session that worked on a project, from every agent, verbatim.

    lab-sessions-export <project-dir> <out-dir> [--since 2026-10-10T00:00] [--extra-dir DIR ...]

A session belongs to the project when its working directory is the project, a
folder inside it, one of its git worktrees, or an --extra-dir. Sources:

  devin   ~/.local/share/devin/cli/sessions.db. Every message node of the session,
          including subagent branches, which the official ATIF export leaves out.
  codex   ~/.codex*/sessions/**/rollout-*.jsonl, copied byte for byte.
  cursor  ~/.cursor/chats/<md5(cwd)>/<chat>/, copied byte for byte, plus the
          decoded JSON messages.

Writes <out-dir>/manifest.json (every session in start order), README.md, and one
folder per agent. Nothing is redacted, because the exports must stay original. A
scan reports secret-shaped strings so a human can decide before sharing.
"""
import argparse, glob, json, os, re, shutil, sqlite3, subprocess, sys
from datetime import datetime, timezone

HOME = os.path.expanduser("~")
SECRET = re.compile(r"(sk-[A-Za-z0-9_-]{20,}|sk_(live|test)_[A-Za-z0-9]{16,}|sbp_[a-f0-9]{20,}|sb_(publishable|secret)_[A-Za-z0-9_-]{16,}|vck_[A-Za-z0-9]{20,}|ghp_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{30,}|eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,})")


def iso(ts):
    if ts is None:
        return None
    ts = ts / 1000 if ts > 1e12 else ts
    return datetime.fromtimestamp(ts, timezone.utc).isoformat()


def roots_for(project, extra):
    roots = {os.path.realpath(project)} | {os.path.realpath(e) for e in extra}
    try:
        out = subprocess.run(["git", "-C", project, "worktree", "list", "--porcelain"],
                             capture_output=True, text=True, timeout=10).stdout
        roots |= {os.path.realpath(l[9:]) for l in out.splitlines() if l.startswith("worktree ")}
    except Exception:
        pass
    return sorted(roots)


def belongs(cwd, roots):
    if not cwd:
        return False
    cwd = os.path.realpath(cwd)
    return any(cwd == r or cwd.startswith(r + os.sep) for r in roots)


def export_devin(roots, since, out):
    db = os.path.join(HOME, ".local/share/devin/cli/sessions.db")
    if not os.path.exists(db):
        return []
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    found = []
    for s in con.execute("select * from sessions order by created_at"):
        dirs = [s["working_directory"]] + json.loads(s["workspace_dirs"] or "[]")
        if not any(belongs(d, roots) for d in dirs):
